#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ucl.h"

int main(int argc, char **argv) {
    if (argc < 2) return 1;
    FILE *f = fopen(argv[1], "rb");
    if (!f) return 1;
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *data = malloc(sz);
    fread(data, 1, sz, f);
    fclose(f);
    struct ucl_parser *parser = ucl_parser_new(0);
    ucl_parser_add_string(parser, data, sz);
    if (ucl_parser_get_error(parser) != NULL) {
        return 0;
    }
    ucl_parser_free(parser);
    free(data);
    return 0;
}
EOF
